Rule.Source:
import sailpoint.object.Identity;

String empId = account.getStringAttribute("employeeId");
identity.setName(empId);
identity.setFirstname(account.getStringAttribute("firstName"));
identity.setLastname(account.getStringAttribute("lastName"));
identity.setDisplayName(account.getStringAttribute("displayName"));
identity.setEmail(account.getStringAttribute("email"));
identity.setAttribute("department", account.getStringAttribute("department"));
identity.setAttribute("title", account.getStringAttribute("title"));
identity.setAttribute("location", account.getStringAttribute("location"));
identity.setAttribute("employeeType", account.getStringAttribute("employeeType"));
identity.setInactive("Terminated".equals(account.getStringAttribute("status")));

String mgrId = account.getStringAttribute("managerId");
if (mgrId != null && mgrId.length() > 0) {
    Identity mgr = context.getObjectByName(Identity.class, mgrId);
    if (mgr != null) identity.setManager(mgr);
}
